116	/// A CSS property pair such as `display: block`.
117	#[derive(Debug, Clone, Eq, PartialEq, Hash)]
118	pub struct Property {
119	    /// The property's name, e.g. `display`.
120	    // TODO: Use something similar to `HtmlAttr`.
121	    pub name: &'static str,
122	    /// The property's serialized value, e.g. `block`.
123	    pub value: EcoString,
124	}
125	
126	impl Property {
127	    /// Creates a new property pair from its parts.
128	    pub fn new(name: &'static str, value: EcoString) -> Self {
129	        Self { name, value }
130	    }
131	}
132	
133	/// Low-level writer for CSS syntax.
134	pub struct CssWriter<'a> {
135	    sink: &'a mut dyn WarningSink,
136	    buf: EcoString,
137	    error: bool,
138	}
139	
140	impl<'a> CssWriter<'a> {
141	    fn new(sink: &'a mut dyn WarningSink) -> Self {
142	        Self { sink, buf: EcoString::new(), error: false }
143	    }
144	
145	    /// Call a CSS function.
146	    fn call<'b>(&'b mut self, name: &str, separator: Separator) -> CallWriter<'a, 'b> {
147	        CallWriter::start(self, name, separator)
148	    }
149	
150	    /// Start a `calc` call expression.
151	    fn calc<'b>(&'b mut self) -> CalcWriter<'a, 'b> {
152	        CalcWriter::start(self)
153	    }
154	
155	    fn emit(&mut self, value: impl ToCss) {
156	        value.emit(self);
157	    }
158	
159	    fn write(&mut self, value: &str) {
160	        self.buf.push_str(value);
161	    }
162	
163	    fn write_fmt(&mut self, value: impl Display) {
164	        write!(&mut self.buf, "{value}").unwrap();
165	    }
166	
167	    fn ignored(&mut self, what: &str) {
168	        self.sink
169	            .emit(eco_format!("{what} was ignored during HTML export").into());
170	    }
171	
172	    fn fail(&mut self, what: &str) {
173	        self.ignored(what);
174	        self.error = true;
175	    }
176	}
177	
178	/// Writes a CSS function call.
179	struct CallWriter<'a, 'b> {
180	    w: &'b mut CssWriter<'a>,
181	    count: usize,
182	    separator: Separator,
183	}
184	
185	impl<'a, 'b> CallWriter<'a, 'b> {
186	    fn start(w: &'b mut CssWriter<'a>, name: &str, separator: Separator) -> Self {
187	        w.write(name);
188	        w.write("(");
189	        Self { w, count: 0, separator }
190	    }
191	
192	    fn arg(&mut self, value: impl ToCss) -> &mut Self {
193	        self.arg_with(value, self.separator)
194	    }
195	
196	    fn arg_with(&mut self, value: impl ToCss, separator: Separator) -> &mut Self {
197	        if self.count > 0 {
198	            self.w.write(match separator {
199	                Separator::Space => " ",
200	                Separator::Slash => " / ",
201	            });
202	        }
203	        self.w.emit(value);
204	        self.count += 1;
205	        self
206	    }
207	}
208	
209	impl Drop for CallWriter<'_, '_> {
210	    fn drop(&mut self) {
211	        self.w.write(")");
212	    }
213	}
214	
215	/// A separator in a CSS function call argument list.
216	#[derive(Debug, Copy, Clone, Eq, PartialEq)]
217	enum Separator {
218	    Space,
219	    Slash,
220	}
221	
222	/// Writes a lazy CSS `calc(<calc-sum>) expression`.
223	/// If only a single operand is written, `calc(<calc-sum>)` is omitted.
224	struct CalcWriter<'a, 'b> {
225	    w: &'b mut CssWriter<'a>,
226	    /// The byte-index in the [`CssWriter::buf`].
227	    start_idx: usize,
228	    count: usize,
229	}
230	
231	impl<'a, 'b> CalcWriter<'a, 'b> {
232	    fn start(w: &'b mut CssWriter<'a>) -> Self {
233	        let start_idx = w.buf.len();
234	        Self { w, start_idx, count: 0 }
235	    }
236	
237	    /// Add a value.
238	    ///
239	    /// - If it is zero, it will be omitted.
240	    /// - If it is negative, it will be negated and subtracted. This makes the
241	    ///   assumption that the formatted string `"+ {val}"` is equivalent to
242	    ///   `"- {val.neg()}"`.
243	    ///   This would for example not be the case if a value somehow implements
244	    ///   [`Ord`] and would be formatted as a non-parenthesized binary operator
245	    ///   with the same or lower precedence, e.g.
246	    ///   `"+ -1pt + 2em"` != `"- 1pt - 2em"`.
247	    fn sum<T>(&mut self, value: T) -> &mut Self
248	    where
249	        T: ToCss + Numeric + Ord,
250	    {
251	        if value == T::zero() {
252	            return self;
253	        }
254	
255	        if self.count == 0 {
256	            self.w.emit(value);
257	        } else {
258	            // Negate the value and subtract it, in case it is negative.
259	            if value < T::zero() {
260	                self.w.write(" - ");
261	                self.w.emit(value.neg());
262	            } else {
263	                self.w.write(" + ");
264	                self.w.emit(value);
265	            }
266	        }
267	        self.count += 1;
268	        self
269	    }
270	}
271	
272	impl Drop for CalcWriter<'_, '_> {
273	    fn drop(&mut self) {
274	        match self.count {
275	            0 => {
276	                // An empty `calc()` function call is invalid, so write a `0`,
277	                // which is also valid for lengths.
278	                self.w.write("0");
279	            }
280	            1 => (),
281	            2.. => {
282	                // TODO: Use insert_str once merged:
283	                // https://github.com/typst/ecow/pull/59
284	                let mut buf = EcoString::with_capacity(self.w.buf.len() + 6);
285	
286	                // NOTE: This assumes the `ToCss` implementation of all values
287	                // should only modify text that itself has written into the
288	                // buffer, which seems reasonable.
289	                buf.push_str(&self.w.buf[..self.start_idx]);
290	                buf.push_str("calc(");
291	                buf.push_str(&self.w.buf[self.start_idx..]);
292	                buf.push_str(")");
293	
294	                self.w.buf = buf;
295	            }
296	        }
297	    }
298	}
299	
300	/// Serializes a value into CSS.
301	pub trait ToCss {
302	    /// Writes `self` into the writer.
303	    fn emit(&self, w: &mut CssWriter);
304	
305	    /// Convert to a string.
306	    fn to_css(&self, mut sink: impl WarningSink) -> EcoString {
307	        let mut w = CssWriter::new(&mut sink);
308	        self.emit(&mut w);
309	        w.buf
310	    }
311	}
312	
313	impl<T: ToCss + ?Sized> ToCss for &T {
314	    fn emit(&self, w: &mut CssWriter) {
315	        (**self).emit(w);
316	    }
317	}
318	
319	impl ToCss for str {
320	    fn emit(&self, w: &mut CssWriter) {
321	        w.write(self);
322	    }
323	}
324	
325	/// Displays a number with four significant digits.
326	///
327	/// For a number between 0 and 1, four significant digits give us a precision of
328	/// `1/10_000`, which is more than 12 bits (see [`is_very_close`]).
329	struct Number<T: Into<f64>>(T);
330	
331	impl<T: Into<f64> + Copy> ToCss for Number<T> {
332	    fn emit(&self, w: &mut CssWriter) {
333	        w.emit(NumberWithPrecision(self.0, 4));
334	    }
335	}
336	
337	/// Displays a number with N significant digits.
338	struct NumberWithPrecision<T: Into<f64>>(T, i16);
339	
340	impl<T: Into<f64> + Copy> ToCss for NumberWithPrecision<T> {
341	    fn emit(&self, w: &mut CssWriter) {
342	        w.write_fmt(typst_utils::round_with_precision(self.0.into(), self.1));
343	    }
344	}
345	
346	impl ToCss for Abs {
347	    fn emit(&self, w: &mut CssWriter) {
348	        w.emit(Number(self.to_pt()));
349	        w.write("pt");
350	    }
351	}
352	
353	impl ToCss for Em {
354	    fn emit(&self, w: &mut CssWriter) {
355	        w.emit(Number(self.get()));
356	        w.write("em");
357	    }
358	}
359	
360	impl ToCss for Length {
361	    fn emit(&self, w: &mut CssWriter) {
362	        w.calc().sum(self.em).sum(self.abs);
363	    }
364	}
365	
366	impl ToCss for Angle {
367	    fn emit(&self, w: &mut CssWriter) {
368	        w.emit(Number(self.to_deg()));
369	        w.write("deg");
370	    }
371	}
372	
373	impl ToCss for Ratio {
374	    fn emit(&self, w: &mut CssWriter) {
375	        w.emit(NumberWithPrecision(self.get() * 100.0, 2));
376	        w.write("%");
377	    }
378	}
379	
380	impl ToCss for Rel {
381	    fn emit(&self, w: &mut CssWriter) {
382	        w.calc().sum(self.rel).sum(self.abs.em).sum(self.abs.abs);
383	    }
384	}
385	
386	impl ToCss for Paint {
387	    fn emit(&self, w: &mut CssWriter) {
388	        match self {
389	            Self::Solid(color) => w.emit(color),
390	            Self::Gradient(_) => w.fail("gradient"),
391	            Self::Tiling(_) => w.fail("tiling"),
392	        }
393	    }
394	}
395	
396	impl ToCss for Color {
397	    fn emit(&self, w: &mut CssWriter) {
398	        // Convert to ProcessColor (spot colors use their fallback)
399	        let process = self.to_process();
400	        match process {
401	            ProcessColor::Rgb(_) | ProcessColor::Cmyk(_) | ProcessColor::Luma(_) => {
402	                w.emit(process.to_rgb());
403	            }
404	            ProcessColor::Oklab(v) => w.emit(v),
405	            ProcessColor::Oklch(v) => w.emit(v),
406	            ProcessColor::LinearRgb(v) => w.emit(v),
407	            ProcessColor::Hsl(_) | ProcessColor::Hsv(_) => w.emit(process.to_hsl()),
408	        }
409	    }
410	}
411	
412	impl ToCss for Rgb {
413	    fn emit(&self, w: &mut CssWriter) {
414	        let low = self.into_format::<u8, u8>();
415	        let high = low.into_format::<f32, f32>();
416	
417	        // Checks if the 8-bit representation of an f32 RGBA color is [very
418	        // close](is_very_close) to the original. If yes, uses a hex
419	        // representation, otherwise falls back to an `rgb` call.
420	        if is_very_close(self.red, high.red)
421	            && is_very_close(self.blue, high.blue)
422	            && is_very_close(self.green, high.green)
423	            && is_very_close(self.alpha, high.alpha)
424	        {
425	            let (r, g, b, a) = low.into_components();
426	            w.write_fmt(format_args!("#{r:02x}{g:02x}{b:02x}"));
427	            if a != u8::MAX {
428	                w.write_fmt(format_args!("{a:02x}"));
429	            }
430	        } else {
431	            w.call("rgb", Separator::Space)
432	                .arg(to_ratio(self.red))
433	                .arg(to_ratio(self.green))
434	                .arg(to_ratio(self.blue))
435	                .maybe_alpha_arg(self.alpha);
436	        }
437	    }
438	}
439	
440	impl ToCss for Oklab {
441	    fn emit(&self, w: &mut CssWriter) {
442	        w.call("oklab", Separator::Space)
443	            .arg(to_ratio(self.l))
444	            .arg(Number(self.a))
445	            .arg(Number(self.b))
446	            .maybe_alpha_arg(self.alpha);
447	    }
448	}
449	
450	impl ToCss for Oklch {
451	    fn emit(&self, w: &mut CssWriter) {
452	        w.call("oklch", Separator::Space)
453	            .arg(to_ratio(self.l))
454	            .arg(Number(self.chroma))
455	            .arg(to_angle(self.hue.into_degrees()))
456	            .maybe_alpha_arg(self.alpha);
457	    }
458	}
459	
460	impl ToCss for LinearRgb {
461	    fn emit(&self, w: &mut CssWriter) {
462	        w.call("color", Separator::Space)
463	            .arg("srgb-linear")
464	            .arg(to_ratio(self.red))
465	            .arg(to_ratio(self.green))
466	            .arg(to_ratio(self.blue))
467	            .maybe_alpha_arg(self.alpha);
468	    }
469	}
470	
471	impl ToCss for Hsl {
472	    fn emit(&self, w: &mut CssWriter) {
473	        w.call("hsl", Separator::Space)
474	            .arg(to_angle(self.hue.into_degrees()))
475	            .arg(to_ratio(self.saturation))
476	            .arg(to_ratio(self.lightness))
477	            .maybe_alpha_arg(self.alpha);
478	    }
479	}
480	
481	impl ToCss for property::Display {
482	    fn emit(&self, w: &mut CssWriter) {
483	        w.write(self.as_str());
484	    }
485	}
486	
487	/// Adds an alpha component argument to a CSS call if the alpha value is not 1.
488	trait MaybeAlpha {
489	    fn maybe_alpha_arg(&mut self, value: f32);
490	}
491	
492	impl MaybeAlpha for CallWriter<'_, '_> {
493	    fn maybe_alpha_arg(&mut self, value: f32) {
494	        if !is_very_close(value, 1.0) {
495	            self.arg_with(to_ratio(value), Separator::Slash);
496	        }
497	    }
498	}
499	
500	/// Convert a raw degree value into an `Angle`.
501	fn to_angle(degrees: impl Into<f64>) -> Angle {
502	    Angle::deg(degrees.into())
503	}
504	
505	/// Convert a raw value between 0 and 1 to a `Ratio`.
506	fn to_ratio(v: impl Into<f64>) -> Ratio {
507	    Ratio::new(v.into())
508	}
509	
510	/// Whether two component values are close enough that there is no
511	/// difference when encoding them with 12-bit. 12 bit is the highest
512	/// reasonable color bit depth found in the industry.
513	fn is_very_close(a: impl Into<f64>, b: impl Into<f64>) -> bool {
514	    const MAX_BIT_DEPTH: u32 = 12;
515	    const EPS: f64 = 0.5 / 2_i32.pow(MAX_BIT_DEPTH) as f64;
516	    (a.into() - b.into()).abs() < EPS
517	}
